package macro;
import star.common.*;import star.metrics.*;import star.segregatedflow.*;import star.flow.*;import star.base.report.*;import java.nio.file.*;import java.io.*;import java.util.*;
public class SolveMini extends StarMacro {
double val(Simulation s,String n){return s.getReportManager().getReport(n).getReportMonitorValue();}
public void execute(){Simulation s=getActiveSimulation();Path r=Paths.get(s.getSessionPath()).getParent();List<double[]> hist=new ArrayList<>();long wall=System.nanoTime();String state="HOLD_LIMIT";try(BufferedWriter w=Files.newBufferedWriter(r.resolve("history.csv"))){w.write("iteration,solver_s,elapsed_s,CL,CD,Mh,Fx,Fy,pABSmin,mass_relative,min_quality\n");List<Boundary> outer=new ArrayList<>(),inlets=new ArrayList<>();List<Region> regs=new ArrayList<>(s.getRegionManager().getRegions());for(Region reg:regs)for(Boundary b:reg.getBoundaryManager().getBoundaries())if(b.getBoundaryType() instanceof InletBoundary||b.getBoundaryType() instanceof PressureBoundary){outer.add(b);if(b.getBoundaryType() instanceof InletBoundary)inlets.add(b);}MassFlowReport mass=s.getReportManager().createReport(MassFlowReport.class),inlet=s.getReportManager().createReport(MassFlowReport.class);mass.getParts().setObjects(outer);inlet.getParts().setObjects(inlets);
List<Boundary> walls=new ArrayList<>();for(Region rr:regs)for(Boundary b:rr.getBoundaryManager().getBoundaries())if(b.getBoundaryType() instanceof WallBoundary)walls.add(b);MinReport wallP=s.getReportManager().createReport(MinReport.class);wallP.setFieldFunction(s.getFieldFunctionManager().getFunction("AbsolutePressure"));wallP.getParts().setObjects(walls);wallP.setSmooth(false);List<MinReport> floors=new ArrayList<>();for(String ff:List.of("TurbulentKineticEnergy","SpecificDissipationRate")){MinReport m=s.getReportManager().createReport(MinReport.class);m.setFieldFunction(s.getFieldFunctionManager().getFunction(ff));m.getParts().setObjects(regs);m.setSmooth(false);floors.add(m);}List<MaxReport> caps=new ArrayList<>();for(String ff:List.of("Velocity","TurbulentViscosityRatio")){MaxReport m=s.getReportManager().createReport(MaxReport.class);FieldFunction f=s.getFieldFunctionManager().getFunction(ff);m.setFieldFunction(ff.equals("Velocity")?f.getMagnitudeFunction():f);m.getParts().setObjects(regs);caps.add(m);}
Report obsolete=s.getReportManager().getReport("MINI_min_CellQuality");if(obsolete!=null)s.getReportManager().remove(obsolete);MinReport nativeQ=s.getReportManager().createReport(MinReport.class);nativeQ.setPresentationName("MINI_min_LeastSquaresQuality");nativeQ.getParts().setObjects(regs);nativeQ.setFieldFunction(s.getFieldFunctionManager().getFunction("LeastSquaresQuality"));nativeQ.setSmooth(false);
PhysicsContinuum physics=regs.get(0).getPhysicsContinuum();physics.enable(CellQualityRemediationModel.class);if(!s.getSolution().isInitialized())s.getSolution().initializeSolution();StringBuilder functions=new StringBuilder();for(FieldFunction ff:s.getFieldFunctionManager().getObjects())functions.append(ff.getFunctionName()+" | "+ff.getPresentationName()+" | "+ff.getClass().getName()+"\n");Files.writeString(r.resolve("native_field_functions.txt"),functions.toString());for(String ff:List.of("AbsolutePressure","LeastSquaresQuality","FaceValidity","Volume")){MinReport m=(MinReport)s.getReportManager().getReport("MINI_min_"+ff);FieldFunction f=s.getFieldFunctionManager().getFunction(ff);if(f==null)throw new IllegalStateException("Native2D quality field unavailable: "+ff);m.setFieldFunction(f);}for(SolverStoppingCriterion c:s.getSolverStoppingCriterionManager().getObjects())c.setIsUsed(false);if(r.getFileName().toString().matches(".*gentle_start|sealed_demo_delta_0")){SegregatedFlowSolver f=s.getSolverManager().getSolver(SegregatedFlowSolver.class);f.getVelocitySolver().setUrf(.3);f.getPressureSolver().setUrf(.05);}
for(int k=1;k<=900;k++){if(Files.exists(r.getParent().resolve("STOP_MINI.json"))){state="HOLD_RESOURCE";break;}long t=System.nanoTime();s.getSimulationIterator().step(1);double seconds=(System.nanoTime()-t)/1e9,elapsed=(System.nanoTime()-wall)/1e9;double cl=val(s,"MINI_CL"),cd=val(s,"MINI_CD"),mh=val(s,"MINI_Mh"),p=val(s,"MINI_min_AbsolutePressure"),q=val(s,"MINI_min_LeastSquaresQuality"),bal=Math.abs(mass.getReportMonitorValue())/Math.max(1e-20,Math.abs(inlet.getReportMonitorValue()));hist.add(new double[]{cl,cd,mh});w.write(s.getSimulationIterator().getCurrentIteration()+","+seconds+","+elapsed+","+cl+","+cd+","+mh+","+val(s,"MINI_Fx")+","+val(s,"MINI_Fy")+","+p+","+bal+","+q+"\n");w.flush();
if(!Double.isFinite(cl+cd+mh+p+q+bal)||p<=12339.214766776897||q<=0||wallP.getReportMonitorValue()<=12339.214766776897||val(s,"MINI_min_FaceValidity")<.5||val(s,"MINI_min_Volume")<=0||floors.stream().anyMatch(m->m.getReportMonitorValue()<=1.0001e-10)||caps.get(0).getReportMonitorValue()>180||caps.get(1).getReportMonitorValue()>=99999){state="HOLD_PHYSICAL";break;}
if(k>=200&&k%25==0){boolean stable=bal<1e-4;for(int j=0;j<3;j++){double a=0,b=0,lo=Double.POSITIVE_INFINITY,hi=-lo;for(int i=k-25;i<k;i++){double x=hist.get(i)[j];a+=x;lo=Math.min(lo,x);hi=Math.max(hi,x);}for(int i=k-50;i<k-25;i++)b+=hist.get(i)[j];a/=25;b/=25;stable&=Math.abs(a-b)<=.005*Math.max(1e-6,Math.abs(a))&&hi-lo<=.01*Math.max(1e-6,Math.abs(a));}
boolean residual=true;int checked=0;for(Monitor mon:s.getMonitorManager().getObjects())if(mon instanceof ResidualMonitor&&!mon.getPresentationName().equals("Z-momentum")){double[] ys=((ResidualMonitor)mon).getAllYValues();if(ys.length<50){residual=false;continue;}double first=ys[0],last=ys[ys.length-1];residual&=Double.isFinite(last)&&last<=.01*Math.max(1e-30,Math.abs(first));checked++;}if(stable&&residual&&checked>=4){state="NUMERICAL_POC_STABILIZED_NOT_VALIDATED";break;}}
if(elapsed>300){state="HOLD_TIME_BUDGET";break;}}
s.saveState(r.resolve("MINI_result.sim").toString());for(Monitor m:s.getMonitorManager().getObjects())if(m instanceof ResidualMonitor)m.export(r.resolve("residual_"+m.getPresentationName().replaceAll("[^A-Za-z0-9]","_")+".csv").toString());XyzInternalTable tab=(XyzInternalTable)s.getTableManager().getTable("MINI Cp walls");tab.extract();tab.export(r.resolve("Cp_yplus.csv").toString(),",");Files.writeString(r.resolve("SOLVE_STATUS.json"),"{\"status\":\""+state+"\",\"iterations_this_run\":"+hist.size()+",\"elapsed_s\":"+(System.nanoTime()-wall)/1e9+",\"validation\":false,\"DRL_allowed\":false}");
}catch(Exception e){try{s.saveState(r.resolve("MINI_error_"+System.currentTimeMillis()+".sim").toString());Files.writeString(r.resolve("SOLVE_ERROR.txt"),e.toString());}catch(Exception ignored){}throw new RuntimeException(e);}}
}
